class Container:
    def __init__(self, items):
        self.items = items

    def __len__(self):
        return len(self.items)

    # Если нет __bool__, используется __len__: 0 -> False, >0 -> True
    # Можно переопределить:
    def __bool__(self):
        return len(self.items) > 0

c = Container([1, 2])
if c:    # работает благодаря __len__ или __bool__
    print("Непустой")
